={{ (() => {
  const factura = (Array.isArray($json.JsonString) ? $json.JsonString[0] : $json.JsonString) || {};
  let driveId = '';
  try { driveId = $('Download file2').item.json.id || ''; } catch (e) {}
  let clientId = 'default';
  let hashArchivo = '';
  try {
    clientId = $('Recibir PDF2').item.json.body?.client_id || 'default';
    hashArchivo = $('Recibir PDF2').item.json.body?.hash_archivo || '';
  } catch (e) {}

  return JSON.stringify({
    "client_id": clientId,
    "hash_archivo": hashArchivo,
    "origen": "pdf_manual",
    "FECHA": factura.FECHAFACTURA || '',
    "FACTURA": factura.NUMEROFACTURA || '',
    "Categoria": factura.Categoria || 'Otros Gastos Operativos No Clasificados',
    "PROVEEDOR": factura.PROVEEDOR || '',
    "SUB TOTAL": factura['SUB TOTAL'] || '0,00',
    "IVA 1%": factura['IVA 1%'] || '0,00',
    "IVA 2%": factura['IVA 2%'] || '0,00',
    "IVA 4%": factura['IVA otros'] || factura['IVA 4%'] || '0,00',
    "IVA 13%": factura['IVA 13%'] || '0,00',
    "TOTAL": factura.TOTAL || '0,00',
    "Notas": factura.Notas || '',
    "DRIVE_ID": driveId
  });
})() }}
